#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Registers the GitHub App Forgerie logs in through, installs it, and hands its
# public client ID to this machine's Forgerie. Re-runnable: values you entered
# before are offered again. Nothing secret is created or stored here: the app
# needs no client secret, private key, or webhook.
#
#   scripts/github-app-wizard.sh                 # Forgerie on this machine
#   FORGERIE_URL=http://host:8504 scripts/github-app-wizard.sh

TOTAL_STAGES=4
ENV_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/forgerie/github-app.env"
mkdir -p "$(dirname "$ENV_FILE")"
FORGERIE_URL="${FORGERIE_URL:-http://127.0.0.1:8504}"

# GitHub App names are unique across all of GitHub and at most 34 characters.
APP_NAME="Forgerie $(whoami)@$(hostname -s)"
APP_NAME="${APP_NAME:0:34}"
urlencode() { local s="$1" out="" c i; for ((i = 0; i < ${#s}; i++)); do c="${s:i:1}"; case "$c" in [A-Za-z0-9.~_-]) out+="$c" ;; *) out+=$(printf '%%%02X' "'$c") ;; esac; done; printf '%s' "$out"; }

banner "Forgerie: GitHub issues login"

stage "Register the GitHub App"
say "GitHub opens its new-app form with Forgerie's settings filled in:"
note "public, no webhook, Repository permissions → Issues: Read-only."
open_url "https://github.com/settings/apps/new?name=$(urlencode "$APP_NAME")&description=$(urlencode "Lists issues in Forgerie's backlog. Read-only.")&url=https%3A%2F%2Fgithub.com&public=true&webhook_active=false&issues=read"
step "Check the name. If GitHub says it is taken, add a word to it."
step "Under 'Identifying and authorizing users', tick 'Enable Device Flow'. GitHub has no link setting for this one."
step "Leave 'Expire user authorization tokens' ticked. Leave 'Callback URL' empty."
step "Check that 'Webhook → Active' is unticked and 'Repository permissions → Issues' says Read-only."
step "Check that 'Where can this GitHub App be installed?' says 'Any account'."
note "It must be public to install it on an organization, such as korri-os. With no secret, key, or webhook, a public app gives nobody else access."
step "Click 'Create GitHub App'."
pause "Press Enter when GitHub shows the new app's settings page."

stage "Copy the app's client ID and slug"
step "On the app's settings page (General), find 'Client ID'. It starts with Iv."
note "The Client ID is not the App ID, which is a number. Do not generate a client secret or private key."
while true; do
  ask GITHUB_APP_CLIENT_ID "Paste the Client ID:"
  [[ "$GITHUB_APP_CLIENT_ID" =~ ^[A-Za-z0-9._-]{8,64}$ ]] && break
  warn "That does not look like a client ID. Copy the value next to 'Client ID'."
done
step "Find 'Public link', https://github.com/apps/<slug>. The slug is the part after /apps/."
while true; do
  ask GITHUB_APP_SLUG "Type the slug:"
  [[ "$GITHUB_APP_SLUG" =~ ^[a-z0-9][a-z0-9-]{0,99}$ ]] && break
  warn "A slug has only lowercase letters, digits, and dashes."
done
write_env GITHUB_APP_CLIENT_ID "$GITHUB_APP_CLIENT_ID"
write_env GITHUB_APP_SLUG "$GITHUB_APP_SLUG"

stage "Install the app where your repos live"
say "Forgerie can read issues only on repos where this app is installed."
open_url "https://github.com/apps/${GITHUB_APP_SLUG}/installations/new"
step "Pick your personal account, then choose 'All repositories' or the repos you want."
step "Go back to the same page and repeat for each organization, such as korri-os."
note "On an organization you do not own, GitHub sends a request to its owners instead."
pause "Press Enter when the app is installed (or requested) everywhere you need it."

stage "Hand the app to Forgerie"
say "Forgerie at ${FORGERIE_URL} receives the client ID and slug. This is not secret."
reply=""
if reply=$(curl -fsS -X PUT -H 'Content-Type: application/json' \
  --data "{\"clientId\":\"${GITHUB_APP_CLIENT_ID}\",\"slug\":\"${GITHUB_APP_SLUG}\"}" \
  "${FORGERIE_URL}/api/github/app" 2>&1); then
  printf '  %s✓ Forgerie answered%s %s\n' "$GREEN" "$RESET" "$reply"
  say "Next: open the backlog in Forgerie and choose 'Connect GitHub'. Enter the code it shows at github.com/login/device."
else
  SKIPPED+=("Send the app to Forgerie: curl -X PUT -H 'Content-Type: application/json' --data '{\"clientId\":\"${GITHUB_APP_CLIENT_ID}\",\"slug\":\"${GITHUB_APP_SLUG}\"}' ${FORGERIE_URL}/api/github/app")
  warn "Forgerie did not accept it: ${reply}"
  note "If this Forgerie predates GitHub login, deploy it first, then run the command listed at the end."
fi
say "To list a project's issues, add this to the project's .forgerie/config.json:"
note '  { "backlog": { "providers": ["markdown", "github"] } }'
pause "Press Enter to finish."
# ──────────────────────────────────────────────────────────────────────────

finish
